/** The Lab html/v1 insight class kit. */
export const LAB_HTML_KIT_CSS = "/**\n * lab-html-kit.css \u2014 the curated class kit a script's `html` card body writes\n * against (html/v1 hybrid). Embedded into the sandboxed iframe's srcdoc together\n * with a :root block of RESOLVED design-token values (CSS variables do not cross\n * the iframe document boundary, so labHtmlKit.ts inlines the current theme's\n * values and re-injects on theme change).\n *\n * The rule for script authors: don't write your own CSS \u2014 use these classes and\n * the card looks native dreamcontext by default. Classes are prefixed `lk-`.\n *\n * Typography follows the NATIVE renders, not generic dashboard tropes: big\n * values are the display face (NumberCard idiom \u2014 mono is for table cells and\n * aligned columns only), chips are the .lab-badge pair (subtle background +\n * toned text, no border), and tinted surfaces follow the tinted-surface-not-\n * filled-swatch pattern so text on them stays body-contrast in both themes.\n */\n\n* { box-sizing: border-box; }\n\nbody {\n  margin: 0;\n  padding: 2px;\n  font-family: var(--font-family);\n  font-size: 13px;\n  color: var(--color-text);\n  background: transparent;\n  -webkit-font-smoothing: antialiased;\n}\n\n/* \u2500\u2500 Typography \u2500\u2500 */\n.lk-title { font-size: 13px; font-weight: 600; color: var(--color-text); margin: 0 0 6px; }\n.lk-label { font-size: 12px; font-weight: 600; color: var(--color-text-secondary); }\n.lk-muted { font-size: 12px; color: var(--color-text-tertiary); }\n/* The NumberCard idiom: display face, tight tracking, tabular digits. */\n.lk-value {\n  font-family: var(--font-family-display);\n  font-size: 24px;\n  font-weight: 700;\n  letter-spacing: -0.02em;\n  font-variant-numeric: tabular-nums;\n  color: var(--color-text);\n}\n.lk-value--lg { font-size: 32px; }\n.lk-value--sm { font-size: 17px; }\n.lk-unit { font-size: 13px; font-weight: 500; color: var(--color-text-tertiary); margin-left: 3px; }\n/* Mono belongs to ALIGNED COLUMNS (table cells, bar values) \u2014 never headlines. */\n.lk-num { font-family: var(--font-mono); text-align: right; white-space: nowrap; font-variant-numeric: tabular-nums; }\n\n/* \u2500\u2500 Deltas (the NumberCard/MetricTable pair: plain toned text, no box) \u2500\u2500 */\n.lk-delta { font-size: 12.5px; font-weight: 600; }\n.lk-delta--up { color: var(--color-success); }\n.lk-delta--down { color: var(--color-error); }\n.lk-delta--flat { color: var(--color-text-tertiary); }\n\n/* \u2500\u2500 Layout \u2500\u2500 */\n.lk-row { display: flex; align-items: center; gap: 8px; min-width: 0; }\n.lk-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(96px, 1fr)); gap: 8px; }\n.lk-spacer { flex: 1; }\n.lk-divider { border: none; border-top: 1px solid var(--color-border); margin: 10px 0; }\n\n/* \u2500\u2500 Stat tile \u2014 a lighter surface than the chips inside it, so the toned\n     chips keep their separation instead of sinking into the same grey. \u2500\u2500 */\n.lk-stat {\n  display: flex;\n  flex-direction: column;\n  align-items: flex-start;\n  gap: 4px;\n  padding: 10px 12px;\n  border: 1px solid var(--color-border);\n  border-radius: 10px;\n  background: var(--color-bg-secondary);\n}\n\n/* \u2500\u2500 Chip / badge (the .lab-badge pair: subtle background + toned text) \u2500\u2500 */\n.lk-chip {\n  display: inline-flex;\n  align-items: center;\n  padding: 2px 8px;\n  border-radius: 999px;\n  font-size: 11px;\n  font-weight: 600;\n  white-space: nowrap;\n  color: var(--color-text-secondary);\n  background: var(--color-bg-tertiary);\n}\n.lk-chip--accent { color: var(--color-accent); background: var(--color-accent-soft); }\n.lk-chip--good { color: var(--color-success); background: var(--color-success-subtle); }\n.lk-chip--bad { color: var(--color-error); background: var(--color-error-subtle); }\n\n/* \u2500\u2500 Callout \u2014 reader-facing emphasis box: tinted SURFACE, body text on top\n     (tinted-surface-not-filled-swatch \u2014 never a solid accent fill for prose). \u2500\u2500 */\n.lk-callout {\n  padding: 8px 10px;\n  border-radius: 8px;\n  background: color-mix(in srgb, var(--color-accent) 12%, var(--color-bg-tertiary));\n  border: 1px solid color-mix(in srgb, var(--color-accent) 40%, var(--color-border));\n  color: var(--color-text);\n  font-size: 12.5px;\n}\n\n/* \u2500\u2500 Table (the MetricTable idiom) \u2500\u2500 */\n.lk-table { width: 100%; border-collapse: collapse; font-size: 12.5px; border: 1px solid var(--color-border); border-radius: 8px; overflow: hidden; }\n.lk-table th { text-align: left; padding: 6px 10px; font-weight: 600; font-size: 12px; color: var(--color-text-secondary); background: var(--color-bg-tertiary); }\n.lk-table th.lk-num, .lk-table td.lk-num { text-align: right; }\n.lk-table td { padding: 5px 10px; border-top: 1px solid var(--color-border); color: var(--color-text); }\n\n/* \u2500\u2500 Bar row (the BarList idiom) \u2500\u2500 */\n.lk-bar { display: flex; align-items: center; gap: 8px; font-size: 12.5px; min-width: 0; }\n.lk-bar-label { flex: 0 0 34%; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--color-text-secondary); }\n.lk-bar-track { flex: 1; min-width: 0; height: 8px; border-radius: 4px; background: var(--color-bg-tertiary); overflow: hidden; }\n.lk-bar-fill { display: block; height: 100%; border-radius: 4px; background: var(--chart-1); }\n.lk-bar-fill--2 { background: var(--chart-2); }\n.lk-bar-fill--3 { background: var(--chart-3); }\n.lk-bar-fill--4 { background: var(--chart-4); }\n.lk-bar-fill--5 { background: var(--chart-5); }\n.lk-bar-fill--6 { background: var(--chart-6); }\n.lk-bar-fill--7 { background: var(--chart-7); }\n.lk-bar-fill--8 { background: var(--chart-8); }\n.lk-bar-value { flex-shrink: 0; font-family: var(--font-mono); font-size: 12px; font-variant-numeric: tabular-nums; color: var(--color-text); }\n\n/* \u2500\u2500 Honesty helpers \u2500\u2500 */\n.lk-low-sample { opacity: 0.45; }\n.lk-empty { color: var(--color-text-tertiary); font-size: 13px; padding: 24px 0; }\n";

/** The Lab frame height bridge. */
export const HTML_HEIGHT_BRIDGE = "(function () {\n  var last = -1;\n  function report(force) {\n    if (!document.body) return;\n    var h = Math.ceil(document.body.getBoundingClientRect().height);\n    if (h === last && !force) return;\n    last = h;\n    parent.postMessage({ __dreamLabHtmlHeight: h }, '*');\n  }\n  window.addEventListener('message', function (event) {\n    if (event.source !== parent || !event.data) return;\n    if (event.data.__dreamLabHtmlMeasure === true) report(true);\n  });\n  function start() {\n    if (window.ResizeObserver) new ResizeObserver(function () { report(false); }).observe(document.body);\n    // An author's own inline script may open a detail or switch a tab on click.\n    document.addEventListener('click', function () { setTimeout(function () { report(false); }, 0); }, true);\n    report(true);\n  }\n  if (document.body) start();\n  else document.addEventListener('DOMContentLoaded', start);\n  // A late web font or an image finishing decode changes the height after the\n  // observer's first callback, so load is a second chance, not a duplicate.\n  window.addEventListener('load', function () { report(false); });\n})();";

/** Mirror of the dashboard's Lab `buildSrcdoc`: an html/v1 insight body. */
export function buildLabSrcdocServer(html: string, tokens: Record<string, string>, scheme: 'light' | 'dark' = 'light'): string {
  return buildSandboxSrcdocServer({ html, css: LAB_HTML_KIT_CSS, tokens, scheme, headScript: HTML_HEIGHT_BRIDGE });
}
